int square(int n) {
  return n * n;
}
print(square(5)); // 25

void greet(String name) { // 'name' is a parameter
  print('Hello, $name!');
}

void myFunc() {
  int x = 10; // local to myFunc
}
print(x); // ERROR: x is not defined here

int factorial(int n) {
  if (n <= 1) return 1; // base case
  return n * factorial(n - 1); // recursive call
}
